fn remove_element(s: &Vec<i32>, k: usize) -> Vec<i32> {
    // We assume `k < s.len()` as per the problem statement.
    let n = s.len();
    // Allocate a new Vec with exactly one less element
    let mut result = Vec::with_capacity(n - 1);
    // Copy all elements before index k
    result.extend_from_slice(&s[..k]);
    // Copy all elements after index k
    result.extend_from_slice(&s[k + 1..]);
    result
}

// Example usage and a simple test
fn main() {
    let original = vec![10, 20, 30, 40, 50];
    let k = 2;
    let without_30 = remove_element(&original, k);
    assert_eq!(without_30, vec![10, 20, 40, 50]);
    // Ensure original is not modified
    assert_eq!(original, vec![10, 20, 30, 40, 50]);
    println!("remove_element passed!");
}